/**
 * Drives the pushed "View More" destination for Technical Timeline -- same shape as
 * [ResolvedCallsListViewModel] (see its doc comment for why this isn't folded into
 * `StockDetailViewModel`), reading `context_vault.event_log` off the same
 * `getStockDetailStream(symbol)` stream instead of `calls.resolved`.
 */
@HiltViewModel
class TechnicalTimelineListViewModel @Inject constructor(
    private val repository: StockAnalysisRepository,
    savedStateHandle: SavedStateHandle
) : ViewModel() {

    private val symbol: String = checkNotNull(savedStateHandle[ARG_SYMBOL]) {
        "TechnicalTimelineListViewModel requires a non-null \"$ARG_SYMBOL\" nav argument"
    }

    private val _isLoading = MutableStateFlow(false)
    private val _error = MutableStateFlow<UiError?>(null)

    val uiState: StateFlow<TechnicalTimelineListUiState> = combine(
        repository.getStockDetailStream(symbol), _isLoading, _error
    ) { detail, isLoading, error ->
        TechnicalTimelineListUiState(
            symbol = symbol,
            events = detail?.contextVault?.eventLog.orEmpty().sortedByDescending { it.date ?: "" },
            isLoading = isLoading && detail == null,
            error = error
        )
    }.stateIn(
        scope = viewModelScope,
        started = SharingStarted.WhileSubscribed(5000),
        initialValue = TechnicalTimelineListUiState(symbol = symbol, isLoading = true)
    )

    /** Called by the UI when the screen becomes visible. */
    fun onStart() {
        fetchDetail(force = false)
    }

    /** Clears any active error (e.g. after a Snackbar is dismissed). */
    fun clearError() {
        _error.value = null
    }

    private fun fetchDetail(force: Boolean) {
        viewModelScope.launch {
            _isLoading.value = true
            _error.value = null

            val result = repository.refreshDetail(symbol, force)

            if (result.isFailure) {
                _error.value = result.exceptionOrNull().toUiError()
            }

            _isLoading.value = false
        }
    }

    companion object {
        /** Must match the nav argument name in the `technicalTimelineList/{symbol}` route. */
        const val ARG_SYMBOL = "symbol"
    }
}
